GLOSSARY = [
 {"term": "bilayer", "plain": "a strip made of two glued layers that behave differently, so it bends when one layer swells."},
 {"term": "green part", "plain": "a printed part that is not yet fully hardened; it still has unreacted chemistry on board."},
 {"term": "post-cure", "plain": "a second hardening step with light (and sometimes heat) after washing."},
 {"term": "IPA", "plain": "isopropyl alcohol, the rubbing-alcohol solvent used to wash uncured resin off prints."},
 {"term": "resin", "plain": "the liquid plastic that a resin printer hardens with light."},
 {"term": "Open Material Mode", "plain": "a paid unlock that lets a Formlabs printer use other companies' resins."},
 {"term": "tank / cartridge", "plain": "the shallow tray where printing happens, and the bottle that refills it."},
 {"term": "warping / curl", "plain": "a part changing shape because it shrinks or swells unevenly."},
 {"term": "ceiling 3/2", "plain": "the proven upper limit on how much a two-layer strip can curve for a given swelling difference."},
 {"term": "modulus", "plain": "how stiff a material is; a high number is stiff."},
 {"term": "secant modulus", "plain": "stiffness taken as a straight line from zero to one point on a stress curve; a rough estimate for rubbers."},
 {"term": "differential strain", "plain": "the difference in how much the two layers stretch or swell."},
 {"term": "diffusivity", "plain": "how fast a liquid creeps into a solid."},
 {"term": "Shore A", "plain": "a scale for rubber hardness; lower is softer."},
 {"term": "SLS / Fuse", "plain": "printing by melting nylon powder with a laser."},
 {"term": "early layer merging", "plain": "software changing the first layers so the part sticks to the platform."},
 {"term": "ASTM D471 / D570", "plain": "standard lab tests for how much a plastic swells in liquids or takes up water."},
]

